package club.abelix.games.fakevival.config.defaults;

import org.bukkit.configuration.ConfigurationSection;
import java.util.*;

/** Guarded Java-only registry for the requested 200-recipe progression expansion. */
public final class RequestedRecipes200Defaults {
    private RequestedRecipes200Defaults() {}
    private static final String GROUPS="""
mining|COBBLESTONE|mining|enchanted_cobblestone,enchanted_stone,enchanted_deepslate,enchanted_granite,enchanted_diorite,enchanted_andesite,enchanted_tuff,enchanted_calcite,enchanted_dripstone,enchanted_obsidian,compressed_iron_plate,compressed_gold_plate,compressed_diamond_plate,compressed_emerald_plate,compressed_lapis_plate,compressed_redstone_plate,compressed_quartz_plate,compressed_copper_plate,mining_apprentice_pickaxe,stonebreaker_pickaxe,deepslate_breaker_pickaxe,obsidian_miner_pickaxe,gemstone_drill,deepcore_drill,netherite_core_drill
foraging|OAK_LOG|wood|enchanted_oak_log,enchanted_spruce_log,enchanted_birch_log,enchanted_jungle_log,enchanted_acacia_log,enchanted_dark_oak_log,enchanted_mangrove_log,enchanted_cherry_log,enchanted_bamboo,woodcutters_axe,spruce_harvester_axe,birch_light_axe,jungle_vine_axe,acacia_sun_axe,dark_oak_shadow_axe,mangrove_mud_axe,cherry_silk_axe,forest_master_axe,bamboo_splitter,leaf_collector_shears,vine_cutter,sapling_fertilizer,flower_compactor,foraging_talisman,foraging_ring
farming|WHEAT|farming|enchanted_wheat,enchanted_carrot,enchanted_potato,enchanted_beetroot,enchanted_pumpkin,enchanted_melon,enchanted_sugar_cane,enchanted_cocoa,enchanted_cactus,enchanted_mushroom,farmers_hoe,carrot_cultivator,potato_cultivator,beetroot_cultivator,pumpkin_dicer,melon_dicer,cactus_knife,mushroom_spore_blade,flour,dough,sweet_dough,bread_dough,cake_batter,cookie_dough,mana_cookie
combat|ROTTEN_FLESH|combat|enchanted_rotten_flesh,enchanted_bone,enchanted_string,enchanted_spider_eye,enchanted_gunpowder,enchanted_slimeball,enchanted_magma_cream,enchanted_blaze_rod,enchanted_ender_pearl,enchanted_ghast_tear,undead_sword,bone_blade,spider_silk_bow,venom_dagger,blast_wand,slime_boots,magma_sword,blaze_staff,ender_necklace,ghast_ring,monster_hunter_charm,spider_hunter_ring,slime_guard_chestplate,blazing_helmet,void_blade
fishing|COD|fishing|enchanted_cod,enchanted_salmon,enchanted_pufferfish,enchanted_tropical_fish,enchanted_kelp,enchanted_prismarine_shard,enchanted_prismarine_crystals,basic_fishing_rod_plus,salmon_rod,puffer_rod,tropical_rod,kelp_wrapped_rod,prismarine_rod,crystal_fishing_rod,ocean_master_rod,cod_scale_helmet,salmon_scale_chestplate,puffer_spike_dagger,tropical_charm,kelp_rope_boots,guardian_scale_leggings,sea_lantern_charm,nautilus_totem,fishing_fortune_talisman,fishing_fortune_ring
nether|NETHERRACK|nether|enchanted_netherrack,enchanted_nether_wart,enchanted_soul_sand,enchanted_blackstone,enchanted_basalt,enchanted_end_stone,enchanted_chorus_fruit,enchanted_purpur,netherrack_flame_blade,nether_wart_healing_potion,soul_sand_charm,blackstone_guard_helmet,basalt_hammer,end_stone_guard_helmet,chorus_warp_wand,purpur_magic_staff,nether_runner_boots,wither_guard_charm,end_guard_charm,void_staff,nether_master_ring,end_master_necklace,dragonfire_staff,elytra_wing_boots,nether_star_core_totem
redstone|REDSTONE|redstone|enchanted_redstone_torch,enchanted_repeater,enchanted_comparator,enchanted_observer,enchanted_piston,enchanted_hopper,machine_frame,advanced_machine_frame,super_machine_frame,auto_compactor,super_compactor_3000,recipe_book_upgrade,storage_page_upgrade,ender_storage_upgrade,portable_workbench,portable_furnace,portable_anvil,redstone_engine,copper_engine,hopper_core,observer_lens,piston_core,dispenser_core,dropper_core,targeting_module
accessories|GOLD_NUGGET|adventure_guild|mining_talisman,mining_ring,mining_artifact,farming_talisman,farming_ring,farming_artifact,combat_talisman,combat_ring,combat_artifact,fishing_talisman,fishing_ring,fishing_artifact,speed_charm,defense_charm,health_charm,mana_charm,strength_charm,magic_find_charm,luck_charm,boss_hunter_charm,dungeon_charm,imperial_charm,sea_charm,void_charm,master_adventurer_talisman
""";
    private static final int[] TIERS={50,100,250,500,1000,2500,5000,10000,25000,50000};
    public static void apply(ConfigurationSection root){for(Spec spec:specs()){collection(root,spec);core(root,spec);output(root,spec);recipe(root,spec);}}
    public static Set<String> recipeIds(){Set<String>s=new LinkedHashSet<>();for(Spec p:specs())s.add(recipeId(p));return Set.copyOf(s);}
    public static Set<String> materialIds(){Set<String>s=new LinkedHashSet<>();for(Spec p:specs())s.add(coreId(p));return Set.copyOf(s);}
    public static Set<String> collectionIds(){Set<String>s=new LinkedHashSet<>();for(Spec p:specs())s.add(p.collection());return Set.copyOf(s);}
    private static List<Spec>specs(){List<Spec>s=new ArrayList<>();for(String line:GROUPS.strip().split("\\R")){String[]p=line.split("\\|",4);for(String id:p[3].split(","))s.add(new Spec(id,p[1],p[0],p[2]));}if(s.size()!=200)throw new IllegalStateException("Requested recipe batch must contain 200 IDs");return List.copyOf(s);}
    private static void collection(ConfigurationSection r,Spec s){String b="collections.items."+s.collection();if(!r.isConfigurationSection(b)){r.set(b+".name","&e"+pretty(s.collection())+" Collection");r.set(b+".category",category(s));r.set(b+".icon",s.vanilla());r.set(b+".materials",List.of(s.vanilla()));}for(int t=1;t<=10;t++){String q="collections."+category(s)+"."+s.collection()+".tiers."+t;if(!r.contains(q+".required"))r.set(q+".required",TIERS[t-1]);if(!r.contains(q+".rewards")||r.getStringList(q+".rewards").isEmpty())r.set(q+".rewards",List.of("perk:tier_"+t));}}
    private static void core(ConfigurationSection r,Spec s){String b="custom-items.items."+coreId(s);if(r.isConfigurationSection(b))return;r.set(b+".name","&f"+pretty(s.output())+" Recipe Core");r.set(b+".material",s.vanilla());r.set(b+".type","RECIPE_MATERIAL");r.set(b+".mmo.type","RECIPE_MATERIAL");r.set(b+".category",materialCategory(s));r.set(b+".rarity","COMMON");r.set(b+".random-rarity",false);r.set(b+".mmo.random-roll",false);r.set(b+".mmo.stats",null);r.set(b+".ability.type","none");r.set(b+".ability.mana-cost",0);r.set(b+".consumable.enabled",false);r.set(b+".max-stack-size",64);r.set(b+".guild-sellable",true);r.set(b+".sellall-allowed",true);}
    private static void output(ConfigurationSection r,Spec s){String b="custom-items.items."+s.output();if(r.isConfigurationSection(b))return;String type=type(s.output());r.set(b+".name","&a"+pretty(s.output()));r.set(b+".material",base(type,s));r.set(b+".type",type);r.set(b+".mmo.type",type);r.set(b+".category",outputCategory(type));r.set(b+".rarity",type.equals("RECIPE_MATERIAL")?"UNCOMMON":"RARE");r.set(b+".random-rarity",false);r.set(b+".mmo.random-roll",false);r.set(b+".ability.type","none");r.set(b+".ability.mana-cost",0);r.set(b+".max-stack-size",type.equals("RECIPE_MATERIAL")?64:1);r.set(b+".consumable.enabled",Set.of("FOOD","POTION").contains(type));}
    private static void recipe(ConfigurationSection r,Spec s){String id=recipeId(s),b="recipes."+id;if(!r.isConfigurationSection(b)){r.set(b+".display-name","&a"+pretty(s.output()));r.set(b+".category",recipeCategory(type(s.output())));r.set(b+".result",s.output());r.set(b+".unlock.type","COLLECTION");r.set(b+".unlock.collection",s.collection());r.set(b+".unlock.tier",4);r.set(b+".ingredients.A","custom:"+coreId(s));r.set(b+".amounts.A",24);r.set(b+".ingredients.B","material:"+s.vanilla());r.set(b+".amounts.B",8);r.set(b+".shape",List.of("AB ","   ","   "));}String q="collections."+category(s)+"."+s.collection()+".tiers.4";List<String>x=new ArrayList<>(r.getStringList(q+".rewards"));String reward="recipe:"+id;if(!x.contains(reward))x.add(reward);r.set(q+".rewards",x);}
    private static String recipeId(Spec s){return s.output().equals("super_compactor_3000")?"super_compactor_3000_upgrade_recipe":s.output()+"_recipe";}private static String coreId(Spec s){return s.output()+"_recipe_core";}
    private static String category(Spec s){return switch(s.collection()){case"wood"->"foraging";case"nether"->"magic";case"redstone"->"tools";case"adventure_guild"->"accessories";default->s.collection();};}
    private static String materialCategory(Spec s){return switch(category(s)){case"farming"->"farming_materials";case"foraging"->"foraging_materials";case"combat"->"combat_materials";case"fishing"->"fishing_materials";case"magic"->"magic_materials";default->"mining_materials";};}
    private static String type(String id){if(id.startsWith("enchanted_")||id.startsWith("compressed_")||Set.of("flour","dough","sweet_dough","bread_dough","cake_batter","cookie_dough","sapling_fertilizer","machine_frame","advanced_machine_frame","super_machine_frame","hopper_core","observer_lens","piston_core","dispenser_core","dropper_core","targeting_module").contains(id))return"RECIPE_MATERIAL";if(id.contains("pickaxe")||id.contains("drill"))return"PICKAXE";if(id.contains("axe")||id.contains("splitter")||id.contains("cutter")||id.contains("shears")||id.contains("cultivator")||id.contains("dicer")||id.contains("hoe")||id.contains("knife"))return"TOOL";if(id.contains("bow"))return"BOW";if(id.contains("rod"))return"FISHING_ROD";if(id.contains("wand"))return"WAND";if(id.contains("staff"))return"STAFF";if(id.contains("helmet")||id.contains("chestplate")||id.contains("leggings")||id.contains("boots"))return"ARMOR";if(id.contains("ring")||id.contains("artifact"))return"RING";if(id.contains("necklace"))return"NECKLACE";if(id.contains("charm")||id.contains("talisman"))return"CHARM";if(id.contains("totem"))return"TOTEM";if(id.contains("potion"))return"POTION";if(id.contains("cookie"))return"FOOD";if(id.contains("sword")||id.contains("blade")||id.contains("dagger")||id.contains("hammer"))return"SWORD";return"UTILITY";}
    private static String base(String t,Spec s){return switch(t){case"PICKAXE"->"DIAMOND_PICKAXE";case"TOOL"->"DIAMOND_AXE";case"BOW"->"BOW";case"FISHING_ROD"->"FISHING_ROD";case"WAND","STAFF"->"BLAZE_ROD";case"ARMOR"->"DIAMOND_CHESTPLATE";case"RING"->"GOLD_NUGGET";case"NECKLACE"->"AMETHYST_SHARD";case"CHARM"->"TOTEM_OF_UNDYING";case"TOTEM"->"TOTEM_OF_UNDYING";case"POTION"->"POTION";case"FOOD"->"COOKIE";case"SWORD"->"DIAMOND_SWORD";default->s.vanilla();};}
    private static String outputCategory(String t){return switch(t){case"PICKAXE","TOOL"->"tools";case"BOW","SWORD"->"weapons";case"FISHING_ROD"->"fishing";case"WAND","STAFF"->"magic";case"ARMOR"->"armor";case"RING","NECKLACE","CHARM","TOTEM"->"accessories";case"POTION"->"potions";case"FOOD"->"food";default->"materials";};}private static String recipeCategory(String t){return switch(t){case"PICKAXE","TOOL"->"TOOLS";case"BOW","SWORD"->"WEAPONS";case"FISHING_ROD"->"FISHING_EQUIPMENT";case"WAND","STAFF"->"MAGIC";case"ARMOR"->"ARMOR";case"RING","NECKLACE","CHARM","TOTEM"->"ACCESSORIES";case"POTION"->"POTIONS";case"FOOD"->"FOOD";default->"MATERIALS";};}
    private static String pretty(String v){StringBuilder b=new StringBuilder();for(String p:v.split("_")){if(!b.isEmpty())b.append(' ');b.append(Character.toUpperCase(p.charAt(0))).append(p.substring(1));}return b.toString();}private record Spec(String output,String vanilla,String collection,String group){}
}
